## File Contents

### 1. `/src-tauri/src/main.rs`
```rust
// Prevents additional console window on Windows in release.
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

fn main() {
    tauri::Builder::default()
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}
```

### 2. `/src-tauri/Cargo.toml`
```toml
[package]
name = "ev-dashboard"
version = "0.1.0"
description = "Canadian EV/PHEV/EREV comparison desktop app"
authors = ["Ian McAdam"]
license = ""
repository = ""
edition = "2021"
rust-version = "1.70"

[build-dependencies]
tauri-build = { version = "2", features = [] }

[dependencies]
tauri = { version = "2", features = [] }
serde = { version = "1", features = ["derive"] }
serde_json = "1"

[features]
custom-protocol = ["tauri/custom-protocol"]
```

### 3. `/src/App.tsx`
```typescript
import { useState } from "react";
import { FilterBar } from "./components/FilterBar";
import { BrandList } from "./components/BrandList";
import { CompareTray } from "./components/CompareTray";
import { CompareView } from "./components/CompareView";

function App() {
  const [compareOpen, setCompareOpen] = useState(false);

  return (
    <div className="min-h-screen flex flex-col bg-ink-900 text-ink-100 font-body">
      <header className="px-6 py-4 border-b border-ink-700 bg-ink-800/40 flex items-baseline gap-4">
        <h1 className="font-display text-xl tracking-tight">EV Dashboard</h1>
        <span className="text-xs text-ink-400">
          Canadian EV / PHEV / EREV comparison · Phase 1
        </span>
        <span className="ml-auto text-xs text-ink-500">
          Long-range trims only · Generation-aware · All numbers cited
        </span>
      </header>

      <FilterBar />

      <main className="flex-1">
        <BrandList />
      </main>

      <footer className="px-6 py-3 border-t border-ink-700 bg-ink-800/40 text-xs text-ink-500 flex items-center gap-4">
        <span>Schema v0.1 · Seed data · Verify all numbers before purchase decisions.</span>
        <span className="ml-auto">
          Federal iZEV: paused/uncertain 2026 · Ontario provincial rebate: none
        </span>
      </footer>

      <CompareTray onOpen={() => setCompareOpen(true)} />
      {compareOpen && <CompareView onClose={() => setCompareOpen(false)} />}
    </div>
  );
}

export default App;
```

### 4. `/src/components/VehicleRow.tsx`
```typescript
import type { Vehicle } from "../types";
import { useAppStore } from "../store/useAppStore";
import { cad, km, kw } from "../lib/format";
import { ConfidenceBadge } from "./ConfidenceBadge";

export function VehicleRow({ vehicle }: { vehicle: Vehicle }) {
  const { compareIds, toggleCompare } = useAppStore();
  const isSelected = compareIds.includes(vehicle.id);
  const atCap = compareIds.length >= 4 && !isSelected;

  return (
    <div
      className={`group flex items-center gap-4 px-6 py-3 border-l-2 transition hover:bg-ink-700/40 ${
        isSelected
          ? "border-l-accent-blue bg-accent-blue/5"
          : "border-l-transparent"
      }`}
    >
      <div className="flex-1 min-w-0">
        <div className="flex items-baseline gap-2">
          <span className="font-display text-base text-ink-100">
            {vehicle.model}
          </span>
          <span className="text-xs text-ink-400">
            {vehicle.generation_label}
          </span>
          <span className="text-xs text-ink-300">· {vehicle.trim_label}</span>
          <ConfidenceBadge level={vehicle.overall_confidence} compact />
        </div>
        <div className="flex flex-wrap gap-x-4 gap-y-0.5 text-xs text-ink-400 mt-0.5">
          <span>
            <span className="text-ink-300">{vehicle.powertrain}</span> ·{" "}
            {vehicle.body_style} · {vehicle.drivetrain_variant === "AWD" ? "AWD" : "RWD/FWD"}
          </span>
          <span>Range: <span className="text-ink-100">{km(vehicle.range_km.value)}</span> ({vehicle.range_protocol})</span>
          <span>Peak DC: <span className="text-ink-100">{kw(vehicle.dc_charge_kw_max.value)}</span></span>
          <span>Port: <span className="text-ink-100">{vehicle.port_type}</span></span>
          <span>MSRP: <span className="text-ink-100">{cad(vehicle.msrp_cad.value)}</span></span>
        </div>
      </div>

      <button
        disabled={atCap}
        onClick={() => toggleCompare(vehicle.id)}
        className={`px-3 py-1.5 rounded text-xs font-medium transition whitespace-nowrap ${
          isSelected
            ? "bg-accent-blue text-white"
            : atCap
              ? "bg-ink-700 text-ink-500 cursor-not-allowed"
              : "bg-ink-700 text-ink-200 hover:bg-ink-600"
        }`}
        title={atCap ? "Compare tray full (max 4)" : undefined}
      >
        {isSelected ? "✓ Comparing" : "Add to compare"}
      </button>
    </div>
  );
}
```

All files read successfully. The project is a Tauri-based EV comparison dashboard with a React frontend using TypeScript and Tailwind CSS.
